            return;
        Game->EntitySetAsDrawable(Me, false);
        Game->GiveHeroObject("OBJECT_MAZE_JOURNAL", -1, false);
        while (!Game->IsObjectInThingsPossession("OBJECT_MAZE_JOURNAL", Game->GetHero())) {
