    void Run()
    {
        if (!p->shownIntro) { cutscenes++; p->shownIntro = true; }
        objectives++;
        if (!p->screened) { screens++; p->screened = true; }
        following = true;
        healthBar = 42;
        p->spawned++;
    }
};
